"""The blackboard: the one place agents share data. Evidence goes in with its source; results are named values.

Everything is JSON-serialisable so a board can be dumped to `.swarm/` and replayed in local development.
Single event loop, so no locks; `wait_for` lets a downstream agent start as soon as upstream posts.
"""
import asyncio
import json
import time
from dataclasses import asdict, dataclass, field
from pathlib import Path


@dataclass
class Evidence:
    kind: str            # label agreed between producer and consumer, e.g. "tender.position" (see docs/SWARM.md)
    site: str            # siteId the fact came from
    data: dict           # the extracted facts, as found (no interpretation)
    source: str = ""     # URL / document / mail subject: where exactly it was read
    author: str = ""     # agent name
    note: str = ""       # caveats: superseded? withdrawn? timezone? uncertain?
    ts: float = field(default_factory=time.time)


class Blackboard:
    def __init__(self):
        self.evidence: list[Evidence] = []
        self.results: dict = {}      # named outputs: "quantities", "materials", "prices", "bid", "answer", ...
        self.errors: list[dict] = []
        self._changed = asyncio.Condition()

    async def post(self, item: Evidence) -> None:
        async with self._changed:
            self.evidence.append(item)
            self._changed.notify_all()

    def query(self, kind: str | None = None, site: str | None = None, prefix: bool = False) -> list[Evidence]:
        def match(e: Evidence) -> bool:
            if kind is not None and not (e.kind.startswith(kind) if prefix else e.kind == kind):
                return False
            return site is None or e.site == site
        return [e for e in self.evidence if match(e)]

    async def set(self, key: str, value) -> None:
        async with self._changed:
            self.results[key] = value
            self._changed.notify_all()

    def get(self, key: str, default=None):
        return self.results.get(key, default)

    async def wait_for(self, kind: str | None = None, key: str | None = None, timeout: float = 600):
        """Block until evidence of `kind` exists (returns the list) or result `key` is set (returns it)."""
        def ready():
            if key is not None and key in self.results:
                return self.results[key]
            if kind is not None and self.query(kind):
                return self.query(kind)
            return None
        async with self._changed:
            await asyncio.wait_for(self._changed.wait_for(lambda: ready() is not None), timeout)
        return ready()

    def error(self, agent: str, message: str) -> None:
        self.errors.append({"agent": agent, "error": message, "ts": time.time()})

    def to_json(self) -> dict:
        return {"evidence": [asdict(e) for e in self.evidence], "results": self.results, "errors": self.errors}

    def dump(self, path: Path) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(self.to_json(), ensure_ascii=False, indent=1, default=str), encoding="utf-8")

    @classmethod
    def load(cls, path: Path) -> "Blackboard":
        raw = json.loads(path.read_text(encoding="utf-8"))
        board = cls()
        board.evidence = [Evidence(**e) for e in raw.get("evidence", [])]
        board.results = raw.get("results", {})
        board.errors = raw.get("errors", [])
        return board

"""Model access for agents: concurrency-limited, usage-counted, JSON-friendly. Qwen by default (hosted, free)."""
import asyncio
import json
import re

import models


def parse_json(text: str):
    """The first JSON object/array in a model reply (tolerates ``` fences and chatter)."""
    text = re.sub(r"^```(?:json)?|```$", "", text.strip(), flags=re.M).strip()
    for opener, closer in (("{", "}"), ("[", "]")):
        start, end = text.find(opener), text.rfind(closer)
        if start != -1 and end > start:
            try:
                return json.loads(text[start:end + 1])
            except ValueError:
                continue
    raise ValueError(f"no JSON in model reply: {text[:200]}")


class LLM:
    def __init__(self, max_concurrent: int = 24):
        self._sem = asyncio.Semaphore(max_concurrent)   # team limit is 32 concurrent Qwen calls
        self._client = None
        self.calls = 0
        self.tokens = {"prompt": 0, "completion": 0}

    @property
    def client(self):
        self._client = self._client or models.qwen()
        return self._client

    async def chat(self, messages: list[dict], *, tools: list[dict] | None = None, model: str = models.QWEN_MODEL,
                   **kwargs):
        """One chat completion; returns the message (`.content`, `.tool_calls`)."""
        args = dict(model=model, messages=messages, **kwargs)
        if tools:
            args["tools"] = tools
        async with self._sem:
            reply = await self.client.chat.completions.create(**args)
        self.calls += 1
        if reply.usage:
            self.tokens["prompt"] += reply.usage.prompt_tokens or 0
            self.tokens["completion"] += reply.usage.completion_tokens or 0
        return reply.choices[0].message

    async def ask(self, system: str, user: str, **kwargs) -> str:
        message = await self.chat([{"role": "system", "content": system}, {"role": "user", "content": user}], **kwargs)
        return message.content or ""

    async def ask_json(self, system: str, user: str, retries: int = 1, **kwargs):
        """Ask for JSON; re-ask once with the parse error if the reply is not valid."""
        messages = [{"role": "system", "content": system}, {"role": "user", "content": user}]
        for _ in range(retries + 1):
            reply = (await self.chat(messages, **kwargs)).content or ""
            try:
                return parse_json(reply)
            except ValueError as error:
                messages += [{"role": "assistant", "content": reply},
                             {"role": "user", "content": f"Invalid: {error}. Reply with valid JSON only."}]
        raise ValueError("model did not return valid JSON")

"""Everything an agent gets: the task, the blackboard, the model, the browsers and the clock."""
import time
from dataclasses import dataclass, field

import run as contract
from swarm.blackboard import Blackboard
from swarm.llm import LLM

SUBMIT_MARGIN_S = 75   # the answer must be in ~1 min before the end; this is the hard stop for any work


@dataclass
class Context:
    task: dict
    board: Blackboard
    llm: LLM
    pool: object                      # swarm.browser_pool.BrowserPool (None in unit tests)
    scored: bool = False              # True in a real run (has a run token); False for local scouting
    t0: float = field(default_factory=time.time)

    @property
    def brief(self) -> str:
        return self.task["brief"]

    def site(self, site_id: str) -> dict:
        """The access entry (siteId, url, credentials) of a website, e.g. ctx.site("erp")."""
        for entry in self.task["access"]:
            if entry.get("siteId") == site_id:
                return entry
        raise KeyError(f"no site {site_id!r}; have {[s.get('siteId') for s in self.task['access']]}")

    @property
    def site_ids(self) -> list[str]:
        return [s.get("siteId") for s in self.task["access"]]

    def seconds_left(self) -> float:
        return contract.seconds_left(self.task)

    def time_left(self) -> float:
        """Seconds of useful work left (run clock minus the submit margin)."""
        return self.seconds_left() - SUBMIT_MARGIN_S

    def elapsed(self) -> float:
        return time.time() - self.t0

"""A reusable, model-driven browsing loop: the MODEL decides where to go and what matters; this code only gives it
hands (goto/click/fill/read) and eyes (page text + numbered interactive elements) and keeps the context small.

    result = await browse(ctx, page, goal="...", site_id="erp", on_record=my_callback)

The model calls `record` to stream facts out as it finds them (survives a timeout) and `finish` with a summary.
Per-site knowledge belongs in `goal`/`hints` as general strategy, never as scenario values.
"""
import json
import logging

from swarm.llm import parse_json

log = logging.getLogger("browse")

OBSERVE_JS = """
(frameNo) => {
  const out = []; let n = 0;
  document.querySelectorAll('a,button,input,select,textarea,summary,[role=button],[role=tab],[role=link],[onclick]')
    .forEach(e => {
      const r = e.getBoundingClientRect(), s = getComputedStyle(e);
      if (r.width < 1 || r.height < 1 || s.visibility === 'hidden' || s.display === 'none') return;
      n += 1; e.setAttribute('data-sw', n);
      const label = (e.innerText || e.value || e.placeholder || e.getAttribute('aria-label') || e.title || '').trim().slice(0, 70);
      out.push({id: frameNo + '.' + n, tag: e.tagName.toLowerCase(), type: e.type || '', label,
                name: e.name || '', href: (e.getAttribute('href') || '').slice(0, 90)});
    });
  return {text: document.body ? document.body.innerText : '', els: out};
}
"""

TOOLS = [
    {"type": "function", "function": {"name": name, "description": desc, "parameters": {
        "type": "object", "properties": props, "required": list(props)}}}
    for name, desc, props in [
        ("goto", "Open a URL.", {"url": {"type": "string"}}),
        ("click", "Click element by id (from the element list).", {"id": {"type": "string"}}),
        ("fill", "Type text into an input/textarea by id (replaces content).",
         {"id": {"type": "string"}, "text": {"type": "string"}}),
        ("select", "Choose an option (by visible label) in a <select>.",
         {"id": {"type": "string"}, "option": {"type": "string"}}),
        ("press", "Press a key, e.g. Enter, Escape, Tab.", {"key": {"type": "string"}}),
        ("page_text", "Read more of the page text, starting at character offset.", {"offset": {"type": "integer"}}),
        ("back", "Go back in history.", {}),
        ("record", "Save a fact you found (kept even if you run out of time). `kind` names what it is, `data` is an "
                   "object with the facts exactly as shown, `source` says where, `note` any caveat "
                   "(superseded/withdrawn/other timezone/unsure).",
         {"kind": {"type": "string"}, "data": {"type": "object"}, "source": {"type": "string"},
          "note": {"type": "string"}}),
        ("finish", "End the task with a short summary of what was found / done.", {"summary": {"type": "string"}}),
    ]
]

SYSTEM = """You operate a web browser to accomplish a goal, step by step, using the tools.
Each turn you see the page URL, its text, and numbered interactive elements. Rules:
- Dismiss cookie walls/popups, re-login if the session expired (credentials are in the goal), retry on error pages.
- Look for traps: look-alike or superseded records, paging, hidden tabs/iframes, archives, other timezones.
- Use `record` for every relevant fact as soon as you see it. Do not invent values; copy what the page shows.
- Call `finish` when the goal is met or you are stuck. Be efficient."""


async def _observe(page, max_chars: int, offset: int = 0) -> tuple[str, dict]:
    """Page observation text, and a map element-id -> (frame, number)."""
    elements, texts, index = [], [], {}
    for frame_no, frame in enumerate(page.frames):
        try:
            seen = await frame.evaluate(OBSERVE_JS, frame_no)
        except Exception:   # detached / navigating frame
            continue
        if seen["text"].strip():
            texts.append(seen["text"] if frame_no == 0 else f"[iframe {frame_no}] {seen['text']}")
        for el in seen["els"]:
            index[el["id"]] = frame
            href = f" href={el['href']}" if el["href"] else ""
            kind = f"{el['tag']}{':' + el['type'] if el['type'] else ''}"
            elements.append(f"[{el['id']}] {kind} {el['label']!r}{(' name=' + el['name']) if el['name'] else ''}{href}")
    text = "\n".join(texts)
    clipped = text[offset:offset + max_chars]
    more = f"\n…(+{len(text) - offset - max_chars} more chars; use page_text offset={offset + max_chars})" \
        if len(text) > offset + max_chars else ""
    body = f"URL: {page.url}\nTITLE: {await page.title()}\nTEXT:\n{clipped}{more}\nELEMENTS:\n" + "\n".join(elements[:150])
    return body, index


async def _act(page, index: dict, name: str, args: dict) -> str:
    if name == "goto":
        await page.goto(args["url"], wait_until="domcontentloaded", timeout=45000)
    elif name == "back":
        await page.go_back(wait_until="domcontentloaded", timeout=30000)
    elif name == "press":
        await page.keyboard.press(args["key"])
    elif name in ("click", "fill", "select"):
        frame = index.get(str(args["id"]))
        if frame is None:
            return f"unknown element id {args['id']}"
        loc = frame.locator(f'[data-sw="{str(args["id"]).split(".")[1]}"]').first
        if name == "click":
            await loc.click(timeout=10000)
        elif name == "fill":
            await loc.fill(args["text"], timeout=10000)
        else:
            await loc.select_option(label=args["option"], timeout=10000)
    try:
        await page.wait_for_load_state("domcontentloaded", timeout=5000)
    except Exception:
        pass
    return "ok"


async def browse(ctx, page, goal: str, *, site_id: str = "", on_record=None, max_steps: int = 40,
                 max_chars: int = 5000, hints: str = "", author: str = "browse") -> dict:
    """Run the loop until `finish`, `max_steps` or the time budget. Returns {"summary", "records", "steps"}."""
    messages = [{"role": "system", "content": SYSTEM + (f"\n{hints}" if hints else "")},
                {"role": "user", "content": f"GOAL:\n{goal}"}]
    records, summary, offset = [], "", 0
    for step in range(max_steps):
        if ctx.time_left() <= 0:
            summary = summary or "out of time"
            break
        obs, index = await _observe(page, max_chars, offset)
        for m in messages:                       # keep context small: only the latest observation stays in full
            if m["role"] == "user" and m["content"].startswith("OBSERVATION"):
                m["content"] = "OBSERVATION (old, omitted)"
        messages.append({"role": "user", "content": f"OBSERVATION step {step}\n{obs}"})
        reply = await ctx.llm.chat(messages, tools=TOOLS, tool_choice="auto")
        messages.append(reply.model_dump(exclude_none=True) if hasattr(reply, "model_dump") else
                        {"role": "assistant", "content": reply.content or ""})
        if not reply.tool_calls:
            messages.append({"role": "user", "content": "Use a tool. Call `finish` if done."})
            continue
        done = False
        offset = 0
        for call in reply.tool_calls:
            name = call.function.name
            try:
                args = parse_json(call.function.arguments or "{}") if (call.function.arguments or "").strip() else {}
                if name == "finish":
                    summary, done, result = args.get("summary", ""), True, "bye"
                elif name == "record":
                    rec = {"kind": args["kind"], "data": args.get("data", {}), "source": args.get("source") or page.url,
                           "note": args.get("note", ""), "site": site_id, "author": author}
                    records.append(rec)
                    if on_record:
                        await on_record(rec)
                    result = "recorded"
                elif name == "page_text":
                    offset = int(args.get("offset", 0))
                    result = "ok"
                else:
                    result = await _act(page, index, name, args)
            except Exception as error:
                result = f"error: {str(error).splitlines()[0][:200]}"
            messages.append({"role": "tool", "tool_call_id": call.id, "content": result})
        if done:
            break
    return {"summary": summary, "records": records, "steps": step + 1}

